update public.yt_channel_videos t set members=v.new_m, with_members=v.new_w from v
where t.id=v.id and t.tags_manual=false and t.members=v.old_m and coalesce(t.with_members,'{}'::text[])=v.old_w;
select count(*) backed, count(*) filter (where t.members is distinct from b.members or t.with_members is distinct from b.with_members) changed from public.bak_outsider_members_20261104 b join public.yt_channel_videos t using(id);
